import { defineAgent } from "eve";

export default defineAgent({
  model: "openai/gpt-5.6-luna-fast",
});

import MemoryClient from "mem0ai";

// The Mem0 Vercel integration injects MEM0_API_KEY, scoped to your org and project.
// Created lazily so this module can be imported during build without the key present.
let client: MemoryClient | undefined;

export function getMem0(): MemoryClient {
  if (!client) {
    const apiKey = [REDACTED];
    if (!apiKey) {
      throw new Error(
        "MEM0_API_KEY is not set. Install the Mem0 integration from the Vercel Marketplace, " +
          "or run `vercel env pull` for local development.",
      );
    }
    client = new MemoryClient({ apiKey });
  }
  return client;
}

// Memory is scoped per authenticated caller. Unprotected sessions share one id so the
// demo remembers across sessions; add real auth and this becomes per-user automatically.
export function memoryUserId(principalId: string | null | undefined): string {
  return principalId ?? "default-user";
}

import { localDev, placeholderAuth, vercelOidc } from "eve/channels/auth";
import { eveChannel } from "eve/channels/eve";

export default eveChannel({
  auth: [
    // Lets the eve TUI and your own Vercel deployments reach the agent.
    vercelOidc(),
    // Open on localhost for `eve dev` and the REPL; ignored in production.
    localDev(),
    // Safe default: blocks anonymous browser requests in production. Replace
    // with your auth provider (Auth.js, Clerk, ...) so each user gets their own
    // memory, or use `none()` for a public demo where everyone shares memory.
    placeholderAuth(),
  ],
});

import { defineTool } from "eve/tools";
import { z } from "zod";
import { getMem0, memoryUserId } from "../lib/mem0";

export default defineTool({
  description:
    "Save a durable fact or preference about the user to long-term memory. " +
    "Use this whenever the user shares something worth remembering across sessions " +
    "(their name, preferences, goals, or context about their work).",
  inputSchema: z.object({
    content: z
      .string()
      .min(1)
      .describe("A single fact or preference to remember, in natural language."),
  }),
  label: { start: ({ content }) => `Remember: ${content.slice(0, 60)}` },
  async execute({ content }, ctx) {
    const userId = memoryUserId(ctx.session.auth.current?.principalId);
    await getMem0().add([{ role: "user", content }], { userId });
    return { saved: true };
  },
});

import { defineTool } from "eve/tools";
import { z } from "zod";
import { getMem0, memoryUserId } from "../lib/mem0";

export default defineTool({
  description:
    "Search the user's long-term memory for facts relevant to a query. " +
    "Call this before answering anything personal so replies use what you already know about the user.",
  inputSchema: z.object({
    query: z
      .string()
      .min(1)
      .describe("What to look up, e.g. the user's question or the current topic."),
  }),
  label: { start: ({ query }) => `Recall: ${query.slice(0, 60)}` },
  async execute({ query }, ctx) {
    const userId = memoryUserId(ctx.session.auth.current?.principalId);
    const res = (await getMem0().search(query, {
      filters: { user_id: userId },
    })) as unknown;

    // Mem0 returns either an array of memories or an object with a `results` array.
    const items = Array.isArray(res) ? res : ((res as { results?: unknown[] }).results ?? []);
    const memories = (items as Array<{ memory?: string }>)
      .map((item) => item.memory)
      .filter((memory): memory is string => Boolean(memory));

    return { memories };
  },
});
